const src = $input.first();
const j = src.json || {};
const deny = [{ json: { action: 'denied', channel: 'web' } }];
const AS = ['prepared', 'applied', 'interview', 'offer', 'rejected'];

// ---- Telegram message: same shape as the web request, so everything downstream is shared
if (j.message && j.message.chat) {
  const m = j.message;
  const text = String(m.text || '').trim();
  const base = { channel: 'telegram', want: ['cv', 'letter', 'prep'], app_id: 0, status: '' };
  const msg = { chat: { id: m.chat.id }, text };
  let action = 'usage';
  if (m.document) { action = 'upload_cv_tg'; msg.document = m.document; }
  else if (/^\/cv(\s|$)/i.test(text)) { action = 'upload_cv'; msg.text = text.replace(/^\/cv\s*/i, ''); }
  else if (text.toLowerCase() === '/reset') action = 'reset';
  else if (text.toLowerCase() === '/applications') action = 'applications';
  else if (/^https?:\/\//i.test(text) || text.length > 300) action = 'generate';
  return [{ json: Object.assign(base, { action, message: msg }) }];
}

// ---- Web request (webhook): access code, visitor token, action whitelist
const b = j.body || {};
if (String(b.access || '') !== 'copilot-059b8a56') return deny;
const tok = String(b.token || '');
if (!/^[a-z0-9]{16,40}$/.test(tok)) return deny;
const action = String(b.action || '');
const ALLOWED = ['generate', 'upload_cv', 'reset', 'applications', 'set_status', 'profile', 'clear_applications'];
if (!ALLOWED.includes(action)) return deny;
const text = action === 'upload_cv' ? String(b.cv_text || '') : String(b.offer || '').trim();
const status = String(b.status || '').toLowerCase();
if (action === 'set_status' && (!/^\d+$/.test(String(b.app_id || '')) || !AS.includes(status))) return deny;
// what to produce: any of cv / letter / prep (all three if the field is absent)
let want = ['cv', 'letter', 'prep'];
if (b.want !== undefined) {
  const raw = Array.isArray(b.want) ? b.want : String(b.want).split(',');
  want = [...new Set(raw.map(x => String(x).trim().toLowerCase()).filter(x => ['cv', 'letter', 'prep'].includes(x)))];
  if (action === 'generate' && want.length === 0) return deny;
}
const out = { json: { channel: 'web', action, message: { chat: { id: 'web-' + tok }, text }, want, app_id: Number(b.app_id || 0), status } };
if (src.binary) out.binary = src.binary;
return [out];

const r = $input.first().json;
const chat = $('Request').first().json.message.chat.id;
const out = [];
const text = t => out.push({ json: { kind: 'text', text: String(t) } });
const file = async (f, caption) => {
  const data = await this.helpers.prepareBinaryData(Buffer.from(f.b64, 'base64'), f.filename, 'application/pdf');
  out.push({ json: { kind: 'file', caption }, binary: { data } });
};
if (r.ok === false) text(r.error || 'Something went wrong. Please try again.');
else if (r.offer) {
  const o = r.offer;
  text('Prepared for ' + o.company + ' - ' + o.job_title + '.' + ((r.gaps || []).length ? '\n\nNot in your CV, so not claimed:\n- ' + r.gaps.join('\n- ') : ''));
  if (r.cv) await file(r.cv, 'CV tailored for ' + o.company + ' - ' + o.job_title);
  if (r.cv_error) text(r.cv_error);
  if (r.letter) await file(r.letter, 'Cover letter for ' + o.company + ' - ' + o.job_title);
  if (r.letter_error) text(r.letter_error);
}
else if (Array.isArray(r.applications)) {
  text(r.applications.length ? r.applications.map(a => '#' + a.id + ' ' + a.company + ' - ' + a.job_title + ' [' + a.status + ']' + (a.deadline ? ' (deadline ' + a.deadline + ')' : '')).join('\n') : 'No application yet.');
}
else if (r.summary) text(r.summary);
else text('Done.');
return out.length ? out : [{ json: { kind: 'text', text: 'Done.' } }];

const r = $('Request').first().json;
let want = Array.isArray(r.want) ? r.want : [];
if (r.channel === 'telegram') {
  want = ['prep'];
  const yes = n => { try { return $(n).first().json.data.approved === true; } catch (e) { return false; } };
  if (yes('Ask CV')) want.push('cv');
  if (yes('Ask letter')) want.push('letter');
}
return [{ json: { want } }];

const o = $('Read offer').first().json.offer;
const sel = $('Select content').first().json;
const want = $('Want').first().json.want;
const grab = n => { try { return $(n).first().json; } catch (e) { return null; } };
const asFile = x => (x && x.ok === true && x.b64) ? { filename: x.filename, b64: x.b64 } : null;
const cvRes = want.includes('cv') ? grab('Make CV') : null;
const letRes = want.includes('letter') ? grab('Make cover letter') : null;
const prepRes = want.includes('prep') ? grab('Run interview prep') : null;
const web = $('Request').first().json.channel === 'web';
return [{ json: {
  ok: true,
  offer: { company: o.company, job_title: o.job_title, location: o.location || '', deadline: o.deadline || '', offer_url: o.offer_url || '' },
  gaps: Array.isArray(sel.gaps) ? sel.gaps : [],
  cv: asFile(cvRes),
  cv_error: want.includes('cv') && !asFile(cvRes) ? 'The CV could not be generated. Please try again.' : '',
  letter: asFile(letRes),
  letter_error: letRes && !asFile(letRes) ? String(letRes.letter_error || 'The cover letter could not be generated. Please try again.') : '',
  prep: web && prepRes ? String(prepRes.text || '') : ''
} }];

const j = $input.first().json;
const text = String(j.text !== undefined ? j.text : (j.cv_text || '')).replace(/\u0000/g, '').trim().slice(0, 30000);
return [{ json: { cv_text: text, chars: text.length } }];

const rows = $input.all().map(i => i.json).filter(r => r.id !== undefined && r.company);
rows.sort((a, b) => Number(b.id) - Number(a.id));
return [{ json: { ok: true, applications: rows.slice(0, 50).map(r => ({
  id: r.id, company: r.company, job_title: r.job_title, location: r.location || '', deadline: r.deadline || '',
  status: r.status || 'prepared', offer_url: r.offer_url || '', prepared_on: r.prepared_on || ''
})) } }];

const rows = $input.all().map(i => i.json).filter(r => r.item_id);
const profile = {};
for (const r of rows) if (r.section === 'profile') profile[String(r.item_id).replace(/^PR_/, '')] = r.text || '';
const items = rows.filter(r => r.section !== 'profile').map(r => ({
  id: r.item_id, section: r.section, parent: r.parent || '', text: r.text || '', dates: r.dates || '', org: r.org || '', role: r.role || ''
}));
const counts = {};
for (const it of items) counts[it.section] = (counts[it.section] || 0) + 1;
return [{ json: { ok: true, has_profile: items.length > 0, demo: profile.demo === '1', name: profile.name || '', counts, items } }];

// Same shape as what the website POSTs to the webhook (everything under `body`).
// Run with 'Execute workflow' to test the whole pipeline without the site or Telegram.
const offer = [
  'Quantitative Analyst Intern (6 months) - Example Capital, Paris.',
  'About the role: you will support the systematic trading desk with research on equity and rates signals.',
  'Responsibilities: build and backtest signals in Python; clean and analyse large market datasets; write weekly research notes; present results to portfolio managers.',
  'Requirements: enrolled in an engineering, mathematics or finance degree; strong Python and SQL; interest in financial markets and statistics; fluent English.',
  'Start date: February 2027. Location: Paris. Application deadline: 30 November 2026.'
].join('\n');
return [{ json: { body: { token: '9adaf039c4fd48dc4a587f99', access: 'copilot-059b8a56', action: 'generate', offer, want: 'cv,letter,prep' } } }];
